/*!
 * \brief System dependent call to get IEEE node ID.
 *
 * This sample implementation generates a random node ID.
 */
void get_ieee_node_identifier(uuid_node_t *node)
{
	unsigned char seed[16];
	static int inited = 0;
	static uuid_node_t saved_node;

	if (!inited) {
		get_random_info(seed);
		seed[0] |= 0x80;
		memcpy(&saved_node, seed, sizeof(uuid_node_t));
		inited = 1;
	}
	*node = saved_node;
}

/*!
 * \brief System dependent call to get the current system time.
 *
 * Returned as 100ns ticks since Oct 15, 1582, but resolution may be
 * less than 100ns.
 */

#ifdef _WIN32

void get_system_time(uuid_time_t *uuid_time)
{
	ULARGE_INTEGER time;

	GetSystemTimeAsFileTime((FILETIME *)&time);
	/*
	   NT keeps time in FILETIME format which is 100ns ticks since
	   Jan 1, 1601.  UUIDs use time in 100ns ticks since Oct 15, 1582.
	   The difference is 17 Days in Oct + 30 (Nov) + 31 (Dec)
	   + 18 years and 5 leap days.
	 */
	time.QuadPart += (unsigned __int64)(1000 * 1000 * 10) /* seconds */
			 * (unsigned __int64)(60 * 60 * 24)   /* days */
			 * (unsigned __int64)(17 + 30 + 31 + 365 * 18 +
					      5); /* # of days */
	*uuid_time = time.QuadPart;
};

void get_random_info(unsigned char seed[16])
{
	int i;
	for (i = 0; i < 16; i++) {
		unsigned int number;
		rand_s(&number);
		seed[i] = number;
	}
};

