#ifndef UPNP_ENABLE_BLOCKING_TCP_CONNECTIONS

	/* in seconds */
	#define DEFAULT_TCP_CONNECT_TIMEOUT 5

/*!
 * \brief Checks socket connection and wait if it is not connected.
 * It should be called just after connect.
 *
 * \return 0 if successful, else -1.
 */
static int Check_Connect_And_Wait_Connection(
	/*! [in] socket. */
	SOCKET sock,
	/*! [in] result of connect. */
	int connect_res)
{
	struct timeval tmvTimeout = {DEFAULT_TCP_CONNECT_TIMEOUT, 0};
	int result;
	#ifdef _WIN32
	struct fd_set fdSet;
	#else
	fd_set fdSet;
	#endif
	FD_ZERO(&fdSet);
	FD_SET(sock, &fdSet);

	if (connect_res < 0) {
	#ifdef _WIN32
		if (WSAEWOULDBLOCK == WSAGetLastError()) {
	#else
		if (EINPROGRESS == errno) {
	#endif
			result = select(
				(int)sock + 1, NULL, &fdSet, NULL, &tmvTimeout);
			if (result < 0) {
	#ifdef _WIN32
					/* WSAGetLastError(); */
	#else
					/* errno */
	#endif
				return -1;
			} else if (result == 0) {
				/* timeout */
				return -1;
	#ifndef _WIN32
			} else {
				int valopt = 0;
				socklen_t len = sizeof(valopt);
				if (getsockopt(sock,
					    SOL_SOCKET,
					    SO_ERROR,
					    (void *)&valopt,
					    &len) < 0) {
					/* failed to read delayed error */
					return -1;
				} else if (valopt) {
					/* delayed error = valopt */
					return -1;
				}
	#endif
			}
		}
	}

	return 0;
}
#endif /* UPNP_ENABLE_BLOCKING_TCP_CONNECTIONS */

static int private_connect(
	SOCKET sockfd, const struct sockaddr *serv_addr, socklen_t addrlen)
{
#ifndef UPNP_ENABLE_BLOCKING_TCP_CONNECTIONS
	int ret = sock_make_no_blocking(sockfd);
	if (ret != -1) {
		ret = connect(sockfd, serv_addr, addrlen);
		ret = Check_Connect_And_Wait_Connection(sockfd, ret);
		if (ret != -1) {
			ret = sock_make_blocking(sockfd);
		}
	}

	return ret;
#else
	return connect(sockfd, serv_addr, addrlen);
#endif /* UPNP_ENABLE_BLOCKING_TCP_CONNECTIONS */
}

#ifdef _WIN32
struct tm *http_gmtime_r(const time_t *clock, struct tm *result)
{
	if (clock == NULL || *clock < 0 || result == NULL)
		return NULL;

	/* gmtime in VC runtime is thread safe. */
	gmtime_s(result, clock);
	return result;
}
#endif

static int get_hoststr(
	const char *url_str, const char **hoststr, size_t *hostlen)
{
	const char *start;
	const char *finish;
	int ret_code = UPNP_E_INVALID_URL;

	start = strstr(url_str, "//");
	if (!start) {
		goto end_function;
	}
	start += 2;
	finish = strchr(start, '/');
	if (finish) {
		*hostlen = (size_t)(finish - start);
	} else {
		*hostlen = strlen(start);
	}
	*hoststr = start;

	ret_code = UPNP_E_SUCCESS;

end_function:
	return ret_code;
}

